//! The part of the invariants guaranteed only by code (the schema has no triggers) that scanning the source can pin
//! down (docs/architecture.md, "Data").
//!
//! Only non-test code under `apps/web/src` is scanned: `tests.rs`, `*_tests.rs`, `test_support.rs` and the part of a
//! file after `#[cfg(test)] mod tests` do not count, since tests write primary keys directly to build data.

use std::{collections::BTreeSet, path::Path};

/// Auto-increment IDs must be positive, and no trigger checks it. Primary keys are generated by AUTO_INCREMENT; the
/// session has `NO_AUTO_VALUE_ON_ZERO` on (`db/mod.rs`), so an explicit 0 would be stored as 0, which is why code never
/// writes these columns explicitly.
const AUTO_INCREMENT_KEYS: &[(&str, &str)] = &[
    ("gonof_common_credit_ledger", "id"),
    ("gonof_common_honor", "id"),
    ("gonof_common_invite", "id"),
    ("gonof_common_log", "id"),
    ("gonof_common_member", "uid"),
    ("gonof_common_member_api_key", "id"),
    ("gonof_common_member_appeal", "id"),
    ("gonof_common_member_sanction", "id"),
    ("gonof_common_member_token", "id"),
    ("gonof_common_outbox", "eventid"),
    ("gonof_common_report", "id"),
    ("gonof_common_sms_code", "id"),
    ("gonof_forum_attachment", "aid"),
    ("gonof_forum_forum", "fid"),
    ("gonof_forum_post_tableid", "pid"),
    ("gonof_forum_thread", "tid"),
    ("gonof_home_forum_follow", "id"),
    ("gonof_home_message", "id"),
    ("gonof_home_message_thread", "id"),
    ("gonof_home_notification", "id"),
    ("gonof_home_thread_follow", "id"),
];

/// Exceptions: the development fixture and the test-site profile import must reproduce fixed IDs, and each checks that
/// IDs are positive before writing (`ensure!` in `content/seed.rs`, the list validation in `content/profiles.rs`).
const EXPLICIT_KEY_WRITERS: &[(&str, &str)] = &[
    ("content/profiles.rs", "gonof_common_member"),
    ("content/seed.rs", "gonof_common_member"),
    ("content/seed.rs", "gonof_forum_post_tableid"),
    ("content/seed.rs", "gonof_forum_thread"),
];

#[test]
fn only_fixture_imports_write_explicit_auto_increment_keys() {
    let mut writers = BTreeSet::new();
    for (file, text) in production_sources() {
        for (line, table, columns) in inserts(&text) {
            // Listing only the primary key with a NULL value takes the auto-increment (such as inserting
            // pid=NULL into `gonof_forum_post_tableid`); that does not count as writing the primary key explicitly.
            let null_key = columns.len() == 1
                && text
                    .lines()
                    .nth(line - 1)
                    .is_some_and(|source| source.contains("VALUES (NULL)"));
            if let Some((_, key)) = AUTO_INCREMENT_KEYS.iter().find(|(name, _)| *name == table)
                && columns.iter().any(|column| column == key)
                && !null_key
            {
                writers.insert((file.clone(), table.clone(), line));
            }
        }
    }
    let actual: BTreeSet<(String, String)> = writers
        .iter()
        .map(|(file, table, _)| (file.clone(), table.clone()))
        .collect();
    let allowed: BTreeSet<(String, String)> = EXPLICIT_KEY_WRITERS
        .iter()
        .map(|(file, table)| ((*file).to_owned(), (*table).to_owned()))
        .collect();
    assert_eq!(
        actual, allowed,
        "the places that write auto-increment keys explicitly changed: {writers:?}. A new writer either leaves the key to AUTO_INCREMENT, or checks that the id is positive before writing and is listed in EXPLICIT_KEY_WRITERS"
    );
}

#[test]
fn no_update_assigns_an_auto_increment_key() {
    let mut found = Vec::new();
    for (file, text) in production_sources() {
        for (line, table, assigned) in updates(&text) {
            if let Some((_, key)) = AUTO_INCREMENT_KEYS.iter().find(|(name, _)| *name == table)
                && assigned.iter().any(|column| column == key)
            {
                found.push(format!("{file}:{line} {table}.{key}"));
            }
        }
    }
    assert!(
        found.is_empty(),
        "an UPDATE must not change an auto-increment key: {found:?}"
    );
}

/// Notification rows and the member's unread count, which no trigger validates. A notification row's type, column
/// combination and recipient ownership are validated only in `insert` in `notifications/record.rs`, and unread counts
/// are adjusted only in the same module by actual row counts, so nothing else may bypass it to write notification rows
/// or unread counts directly; marking as read may only change `read_at`.
#[test]
fn notification_rows_and_unread_counts_change_only_through_the_record_module() {
    const RECORD: &str = "notifications/record.rs";
    let mut found = Vec::new();
    for (file, text) in production_sources() {
        for (line, table, columns) in inserts(&text) {
            let outside = file != RECORD && table == "gonof_home_notification";
            let counter = table == "gonof_common_member"
                && columns
                    .iter()
                    .any(|column| column == "unread_notifications");
            let preference = table == "gonof_home_notification_preference"
                && file != "notifications/preferences.rs";
            if outside || counter || preference {
                found.push(format!("{file}:{line} INSERT {table}"));
            }
        }
        for (line, table) in deletes(&text) {
            if table == "gonof_home_notification" && file != RECORD {
                found.push(format!("{file}:{line} DELETE {table}"));
            }
        }
        for (line, table, assigned) in updates(&text) {
            let notification = table == "gonof_home_notification"
                && (file != "notifications.rs"
                    || assigned.iter().any(|column| column != "read_at"));
            let counter = table == "gonof_common_member"
                && file != RECORD
                && assigned
                    .iter()
                    .any(|column| column == "unread_notifications");
            let preference = table == "gonof_home_notification_preference";
            if notification || counter || preference {
                found.push(format!("{file}:{line} UPDATE {table} {assigned:?}"));
            }
        }
    }
    assert!(
        found.is_empty(),
        "notification rows and unread counts change only through notifications/record.rs, and marking as read changes only read_at: {found:?}"
    );
}

/// The credits ledger and the activity and credits tables, which no trigger validates or protects. The ledger is
/// append-only and accounts change only in the bookkeeping code (`apply` in `activities/ledger.rs` and zeroing on
/// account deletion), the two cross-checked by credits reconciliation; activity state is written only through an
/// `activities::invariants::State` binding, red packet rows are written only at publication, and claims change only the
/// remaining shares.
#[test]
fn ledgers_are_append_only_and_activity_values_go_through_the_invariants() {
    const LEDGER_WRITERS: &[&str] = &["activities/ledger.rs", "privacy/worker.rs"];
    let mut found = Vec::new();
    for (file, text) in production_sources() {
        for (line, verb, table) in writes(&text) {
            let in_ledger_code = LEDGER_WRITERS.contains(&file.as_str());
            let bad = match table.as_str() {
                "gonof_common_credit_ledger" => verb != "insert" || !in_ledger_code,
                "gonof_common_growth_ledger" => verb != "insert" || file != "growth.rs",
                "gonof_common_credit_account" => {
                    !in_ledger_code || !matches!(verb, "insert" | "update")
                }
                "gonof_forum_redpacket" => match verb {
                    "insert" => file != "activities/campaign.rs",
                    "update" => false,
                    _ => true,
                },
                _ => false,
            };
            if bad {
                found.push(format!("{file}:{line} {verb} {table}"));
            }
        }
        for (line, table, assigned) in updates(&text) {
            if table == "gonof_forum_redpacket"
                && assigned.iter().any(|column| column != "remaining_shares")
            {
                found.push(format!("{file}:{line} UPDATE {table} {assigned:?}"));
            }
        }
        for (line, table, columns) in inserts(&text) {
            if table == "gonof_forum_activity" && columns.iter().any(|column| column == "state") {
                found.push(format!("{file}:{line} INSERT {table} writes state"));
            }
        }
        let mut rest = text.as_str();
        while let Some(start) = rest.find("UPDATE gonof_forum_activity ") {
            let statement = &rest[start..];
            let end = statement[1..]
                .find('"')
                .map_or(statement.len(), |end| end + 1);
            if statement[..end].contains("state='") {
                found.push(format!(
                    "{file} writes an activity state as a literal: {}",
                    &statement[..end]
                ));
            }
            rest = &statement[end..];
        }
    }
    assert!(
        found.is_empty(),
        "ledgers are append-only, accounts change only in the bookkeeping code, and activity states and red packet values go only through activities::invariants: {found:?}"
    );
}

/// Threads, posts, forums, member display columns and the site content version
/// (docs/queries.md, "Rules enforced by the source scan"). The thread row's denormalized copies are rewritten only
/// through `content/copies.rs`, and a new thread's INSERT must write all copies; every UPDATE of a thread row bumps the
/// thread version (`cache_revision`), except the view count's, which is the only statement that writes `views` and
/// writes nothing else (`content/views.rs`; only the fixture and sample import insert threads with a `views` value);
/// changing `fid` writes `family_fid` in the same statement; `displayorder`
/// (negative means not listed) changes only in copies.rs and the pin actions; forum thread counts, member counts and
/// nested replies' `root_invisible` go only through copies.rs; posts' like and downvote counts and threads' favorite
/// and tip counts go only through `interaction/counters.rs`, and the three detail tables are only inserted into or
/// deleted from in files that call it; the site version goes only through `copies::bump_site`; the first post's
/// `first_tid` is written at insert; posts' identity columns, author and time and threads' ID, category and author
/// cannot change (erasure walks a member's posts by author and time, `privacy/worker.rs`); erasure
/// markers are written only by the erasure statements; member and forum columns that feed the copies change only in
/// files that call the `copies` sync. Thread and post rows are never deleted; forum rows are deleted only in
/// `organization.rs`, for empty forums (only forums with no threads and no child forums can be deleted; when there are
/// threads the foreign key blocks it too).
#[test]
fn content_copies_versions_and_identities_change_only_through_their_code() {
    let found = content_breaches(production_sources());
    assert!(
        found.is_empty(),
        "thread copies are rewritten only through content/copies.rs; like, downvote, favorite and tip counts only through interaction/counters.rs; changing the forum also writes the top-level forum id; displayorder changes only in the visibility sync and pinning; forum counts and parent post copies only through copies.rs; every UPDATE of a thread row bumps cache_revision, except the view count's in content/views.rs, the only writer of views; the site version only through bump_site; the first post writes first_tid; post identity, author and time and thread category and author do not change; erasure markers are written only by the erasure statements: {found:?}"
    );
}

/// The view count is written only by `content/views.rs`, by a statement that writes nothing else and leaves
/// `cache_revision` alone; everywhere else a thread UPDATE still bumps `cache_revision` and may not touch `views`, and
/// only the fixture and sample import insert a `views` value.
#[test]
fn only_the_view_counter_writes_views_and_skips_cache_revision() {
    let source = |file: &str, sql: &str| (file.to_owned(), format!("let sql = \"{sql}\";\n"));
    let allowed = [
        source(
            "content/views.rs",
            "UPDATE gonof_forum_thread SET views=views+? WHERE tid=?",
        ),
        source(
            "content/seed.rs",
            "INSERT INTO gonof_forum_thread (tid, author, family_fid, views) VALUES (?,?,?,?)",
        ),
    ];
    assert_eq!(content_breaches(allowed), Vec::<String>::new());
    let refused = [
        source(
            "content/edits.rs",
            "UPDATE gonof_forum_thread SET views=views+1, cache_revision=cache_revision+1 WHERE tid=?",
        ),
        source(
            "content/edits.rs",
            "UPDATE gonof_forum_thread SET views=0 WHERE tid=?",
        ),
        source(
            "content/views.rs",
            "UPDATE gonof_forum_thread SET views=views+?, replies=replies+1 WHERE tid=?",
        ),
        source(
            "content/views.rs",
            "UPDATE gonof_forum_thread SET replies=replies+1 WHERE tid=?",
        ),
        source(
            "content/writes.rs",
            "INSERT INTO gonof_forum_thread (tid, author, family_fid, views) VALUES (?,?,?,?)",
        ),
    ];
    let found = content_breaches(refused);
    assert_eq!(found.len(), 5, "{found:?}");
}

/// The leaderboard totals `gonof_rank_member` are written only by `ranks/counts.rs`.
#[test]
fn only_the_rank_counts_write_the_leaderboard_totals() {
    let source = |file: &str, sql: &str| (file.to_owned(), format!("let sql = \"{sql}\";\n"));
    let statements = [
        "INSERT INTO gonof_rank_member(uid,threads,replies,likes) VALUES(?,?,?,?)",
        "UPDATE gonof_rank_member SET likes=likes+1 WHERE uid=?",
        "DELETE FROM gonof_rank_member",
    ];
    assert_eq!(
        content_breaches(statements.map(|sql| source("ranks/counts.rs", sql))),
        Vec::<String>::new()
    );
    for sql in statements {
        assert!(
            !content_breaches([source("content/copies.rs", sql)]).is_empty(),
            "{sql}"
        );
    }
}

/// Erasure walks a member's posts by author and time (`privacy/worker.rs`), so no statement may give a post another
/// author or time.
#[test]
fn posts_keep_their_author_and_time() {
    let source = |sql: &str| {
        (
            "content/edits.rs".to_owned(),
            format!("let sql = \"{sql}\";\n"),
        )
    };
    let found = content_breaches([
        source("UPDATE gonof_forum_post SET dateline=? WHERE pid=?"),
        source("UPDATE gonof_forum_post SET authorid=NULL,version=version+1 WHERE pid=?"),
    ]);
    assert_eq!(found.len(), 2, "{found:?}");
}

/// The breaches of [`content_copies_versions_and_identities_change_only_through_their_code`] in `sources` (file path
/// under `apps/web/src`, text).
fn content_breaches(sources: impl IntoIterator<Item = (String, String)>) -> Vec<String> {
    const COPIES: &str = "content/copies.rs";
    // The view count is buffered and added by one statement that leaves the thread version alone
    // (docs/queries.md, "Views").
    const VIEWS: &str = "content/views.rs";
    // Only the author name and top-level forum ID are copied onto the thread row (not the forum name, URL, inherited
    // scope or author avatar).
    const THREAD_COPIES: &[&str] = &["author", "family_fid"];
    // Unlisted threads have a negative displayorder, rewritten only by the first-post hiding sync
    // (copies.rs) and the pin actions (edits.rs); the two count tables and nested replies' parent floor copies change
    // only through copies.rs.
    const DISPLAYORDER_WRITERS: &[&str] = &[COPIES, "content/edits.rs"];
    const COUNTERS: &[&str] = &["gonof_forum_thread_count", "gonof_common_member_count"];
    // The leaderboard totals change only through ranks/counts.rs, in the transactions that change what they count.
    const RANK_COUNTS: &str = "ranks/counts.rs";
    // Posts' like and downvote counts and threads' favorite count, tip count and tip total are written only through
    // interaction/counters.rs; the three detail tables for likes, downvotes and favorites are only inserted into or
    // deleted from in files that call the counter code alongside.
    const MARK_COUNTERS: &str = "interaction/counters.rs";
    const POST_MARK_COUNTS: &[&str] = &["reactions", "downvotes"];
    const THREAD_MARK_COUNTS: &[&str] = &["favorites", "tips", "tip_total"];
    const MARKS: &[&str] = &[
        "gonof_forum_post_reaction",
        "gonof_forum_post_downvote",
        "gonof_home_favorite",
    ];
    const MARK_WRITERS: &[&str] = &["interaction.rs", MARK_COUNTERS, "growth.rs"];
    const CONTENT_INSERTERS: &[&str] = &["content/writes.rs", "content/seed.rs"];
    const LAST_REPLY_WRITERS: &[&str] = &["content/writes.rs", "content.rs", COPIES];
    const POST_IDENTITY: &[&str] = &[
        "pid",
        "tid",
        "fid",
        "first",
        "first_tid",
        "position",
        "root_pid",
        "reply_to_pid",
        "root_position",
        "sub_position",
    ];
    // Avatars are not copied into threads (list avatars are addressed by uid).
    const MEMBER_DISPLAY: &[&str] = &["username", "account_state"];
    const MEMBER_DISPLAY_WRITERS: &[&str] = &[
        "identity/profile.rs",
        "media/avatar.rs",
        "privacy/worker.rs",
    ];
    let mut found = Vec::new();
    let has = |columns: &[String], name: &str| columns.iter().any(|column| column == name);
    for (file, text) in sources {
        let file = file.as_str();
        for (line, table, columns) in inserts(&text) {
            let bad = match table.as_str() {
                "gonof_forum_thread" => {
                    !CONTENT_INSERTERS.contains(&file)
                        || THREAD_COPIES.iter().any(|copy| !has(&columns, copy))
                        || (file != "content/seed.rs" && has(&columns, "views"))
                }
                table if COUNTERS.contains(&table) => file != COPIES,
                "gonof_rank_member" => file != RANK_COUNTS,
                "gonof_forum_post" => {
                    !CONTENT_INSERTERS.contains(&file) || !has(&columns, "first_tid")
                }
                "gonof_forum_forum" => !matches!(file, "organization.rs" | "content/seed.rs"),
                _ => false,
            };
            if bad {
                found.push(format!("{file}:{line} INSERT {table} {columns:?}"));
            }
        }
        for (line, verb, table) in writes(&text) {
            let bad = match table.as_str() {
                "gonof_common_content_revision" => verb != "update" || file != COPIES,
                table if COUNTERS.contains(&table) => {
                    !(file == COPIES || (verb == "delete" && file == "organization.rs"))
                }
                "gonof_rank_member" => file != RANK_COUNTS,
                "gonof_forum_thread" | "gonof_forum_post" => !matches!(verb, "insert" | "update"),
                "gonof_forum_forum" => {
                    !matches!(verb, "insert" | "update")
                        && !(verb == "delete" && file == "organization.rs")
                }
                table if MARKS.contains(&table) => !MARK_WRITERS.contains(&file),
                _ => false,
            };
            if bad {
                found.push(format!("{file}:{line} {verb} {table}"));
            }
        }
        for (line, table, assigned) in updates(&text) {
            let any = |names: &[&str]| {
                assigned
                    .iter()
                    .any(|column| names.contains(&column.as_str()))
            };
            let bad = match table.as_str() {
                "gonof_forum_thread" if file == VIEWS => assigned != ["views"],
                "gonof_forum_thread" => {
                    !has(&assigned, "cache_revision")
                        || has(&assigned, "views")
                        || (file != COPIES && any(THREAD_COPIES))
                        || (!DISPLAYORDER_WRITERS.contains(&file) && has(&assigned, "displayorder"))
                        || (has(&assigned, "fid") && !has(&assigned, "family_fid"))
                        || (!LAST_REPLY_WRITERS.contains(&file)
                            && any(&["last_reply_author", "last_reply_uid"]))
                        || any(&["category", "authorid"])
                        || (file != MARK_COUNTERS && any(THREAD_MARK_COUNTS))
                }
                "gonof_forum_post" => {
                    any(POST_IDENTITY)
                        || any(&["authorid", "dateline"])
                        || (file != "privacy/worker.rs" && has(&assigned, "erased_at"))
                        || (file != COPIES && has(&assigned, "root_invisible"))
                        || (file != MARK_COUNTERS && any(POST_MARK_COUNTS))
                }
                table if COUNTERS.contains(&table) => file != COPIES,
                "gonof_rank_member" => file != RANK_COUNTS,
                "gonof_forum_forum" => file != "organization.rs",
                "gonof_forum_activity" => has(&assigned, "kind"),
                "gonof_common_member" => {
                    !MEMBER_DISPLAY_WRITERS.contains(&file) && any(MEMBER_DISPLAY)
                }
                _ => false,
            };
            if bad {
                found.push(format!("{file}:{line} UPDATE {table} {assigned:?}"));
            }
        }
    }
    found
}

/// Identity and moderation tables, which have no triggers. Values are guaranteed before writing by `identity/rules.rs`
/// and each entry point's validation; this pins "forward only" and "immutable":
/// - tokens, API tokens and invite codes are inserted only through the entry points in `identity/rules.rs`, and API
///   tokens are revoked only there;
/// - a token is redeemed or revoked only once (`WHERE` with two `IS NULL`), at a time no earlier than issuance; invite
///   codes only change state, with `used`, the user and the registration time in the same statement;
/// - account state changes only in the account deletion flow and only moves forward; a sanction ends only once,
///   reports and appeals are handled only once, and original content never appears in `SET`;
/// - appeals, sanctions and reports cannot be deleted; a data request's 7 submitted fields
///   never change, its upper bound only grows, and its version only increments by one;
/// - logs, rename records and role applications never change; settings keys and site asset slots never change; an
///   Outbox entry's due time is no earlier than enqueueing, and there are only 4 states.
#[test]
fn identity_and_governance_rows_change_only_through_their_rules() {
    const RULES: &str = "identity/rules.rs";
    const OUTBOX_STATUSES: &[&str] = &["pending", "processing", "sent", "failed"];
    let mut found = Vec::new();
    for (file, text) in production_sources() {
        let file = file.as_str();
        for (line, table, _) in inserts(&text) {
            let allowed: &[&str] = match table.as_str() {
                "gonof_common_member_token"
                | "gonof_common_member_api_key"
                | "gonof_common_invite" => &[RULES],
                "gonof_common_member" => &["identity.rs", "content/profiles.rs", "content/seed.rs"],
                "gonof_common_member_sanction" => &["moderation/sanctions.rs"],
                "gonof_common_report" => &["moderation/reports.rs"],
                "gonof_common_member_appeal" => &["moderation/appeals.rs"],
                "gonof_common_data_request" => &["privacy.rs"],
                "gonof_common_member_username_history" => {
                    &["identity/profile.rs", "privacy/worker.rs"]
                }
                "gonof_common_member_role_request" => &["identity.rs"],
                "gonof_common_site_asset" => &["media/branding.rs"],
                // The two multi-domain site tables are written only by domains/write.rs.
                "gonof_common_site_domain" | "gonof_common_site_domain_forum" => {
                    &["domains/write.rs"]
                }
                // SMS verification codes are issued only by the phone number module.
                "gonof_common_sms_code" => &["identity/phone.rs"],
                // Third-party links are written only by the linking module (two places: registration and
                // linking).
                "gonof_common_member_external" => &["identity/external.rs"],
                _ => continue,
            };
            if !allowed.contains(&file) {
                found.push(format!("{file}:{line} INSERT {table}"));
            }
        }
        for (line, verb, table) in writes(&text) {
            let bad = matches!(
                table.as_str(),
                "gonof_common_site_domain" | "gonof_common_site_domain_forum"
            ) && file != "domains/write.rs"
                // Verification code rows: the phone number module updates the wrong-attempt count and the used time,
                // and ends a code it could not deliver; account deletion and the cleanup job delete them.
                || table == "gonof_common_sms_code"
                    && match verb {
                        "delete" => !matches!(file, "privacy/worker.rs" | "maintenance.rs"),
                        _ => file != "identity/phone.rs",
                    }
                // Third-party links: the linking module unlinks them and records the last login time; they are deleted
                // on account deletion.
                || table == "gonof_common_member_external"
                    && match verb {
                        "delete" => !matches!(file, "identity/external.rs" | "privacy/worker.rs"),
                        _ => file != "identity/external.rs",
                    }
                || verb == "delete"
                    && matches!(
                        table.as_str(),
                        "gonof_common_member_appeal"
                            | "gonof_common_member_sanction"
                            | "gonof_common_report"
                            | "gonof_common_data_request"
                            | "gonof_common_member_api_key"
                            | "gonof_common_invite"
                            | "gonof_common_member_role_request"
                            | "gonof_common_site_asset"
                    )
                || matches!(verb, "replace" | "truncate")
                    && table.starts_with("gonof_common_")
                    && !table.starts_with("gonof_common_credit")
                    && !table.starts_with("gonof_common_growth");
            if bad {
                found.push(format!("{file}:{line} {verb} {table}"));
            }
        }
        for (line, table, set, condition) in update_texts(&text) {
            let assigned = assigned_columns(&set);
            let only = |names: &[&str]| {
                assigned
                    .iter()
                    .all(|column| names.contains(&column.as_str()))
            };
            let assigns = |name: &str| assigned.iter().any(|column| column == name);
            let set = squeeze(&set);
            let condition = squeeze(&condition);
            let bad = match table.as_str() {
                "gonof_common_member" => {
                    (assigns("account_state")
                        && (file != "privacy/worker.rs"
                            || !condition.contains("account_state=")
                            || set.contains("'active'")))
                        || (assigns("adminid")
                            && !matches!(file, "identity.rs" | "privacy/worker.rs"))
                        // The mute copy is rewritten only when a sanction is issued, revoked or expires.
                        || (assigns("mute_until") && file != "moderation/sanctions.rs")
                        // The phone number is only bound, rebound or unbound through SMS verification codes, and is
                        // cleared on account deletion.
                        || (assigns("mobile")
                            && !matches!(file, "identity/phone.rs" | "privacy/worker.rs"))
                        || (assigns("password")
                            && !matches!(
                                file,
                                "identity/security.rs"
                                    | "content/profiles.rs"
                                    | "privacy/worker.rs"
                            ))
                        || ((assigns("email") || assigns("emailstatus"))
                            && !matches!(
                                file,
                                "identity.rs"
                                    | "identity/profile.rs"
                                    | "content/profiles.rs"
                                    | "privacy/worker.rs"
                            ))
                }
                // A link row only records the last time it was used to log in, no earlier than the link time; the
                // identity, member and display name never change.
                "gonof_common_member_external" => {
                    !only(&["last_login_at"]) || !set.contains("last_login_at=greatest(dateline,")
                }
                // A code is written as not delivered (it ends at its issue time) and gets its lifetime once, when the
                // provider took it: only a row still undelivered may get one. Otherwise a code only loses validity.
                "gonof_common_sms_code" => {
                    !only(&["attempts", "consumed_at", "expires_at"])
                        || (assigns("consumed_at")
                            && (!set.contains("consumed_at=greatest(dateline,")
                                || !condition.contains("consumed_atisnull")))
                        || (assigns("expires_at")
                            && set != "expires_at=dateline"
                            && !(set == "expires_at=?"
                                && condition.contains("expires_at=dateline")))
                }
                "gonof_common_member_token" => {
                    !only(&["consumed_at", "revoked_at"])
                        || !condition.contains("consumed_atisnull")
                        || !condition.contains("revoked_atisnull")
                        || (assigns("revoked_at")
                            && !(set.contains("revoked_at=greatest(dateline,")
                                || set.contains("revoked_at=casewhendateline>")))
                        || (assigns("consumed_at")
                            && !set.contains("consumed_at=greatest(dateline,")
                            && !condition.contains("dateline<=?"))
                }
                "gonof_common_member_api_key" => {
                    !only(&["revoked_at", "revoked_by", "last_used_at", "last_used_ip"])
                        || (assigns("revoked_at")
                            && (file != RULES
                                || !set.contains("revoked_at=greatest(dateline,")
                                || !condition.contains("revoked_atisnull")))
                        || (assigns("revoked_by") && !assigns("revoked_at"))
                        || (assigns("last_used_at") && !condition.contains("dateline<=?"))
                }
                "gonof_common_invite" => {
                    !only(&["status", "fuid", "regdateline"])
                        || !condition.contains("status")
                        || set.contains("'used'")
                        || (assigns("fuid") || assigns("regdateline"))
                            && !(assigns("status") && assigns("fuid") && assigns("regdateline"))
                }
                "gonof_common_member_sanction" => {
                    !only(&["revoked_at", "revoked_by"]) || !condition.contains("revoked_at=0")
                }
                "gonof_common_report" | "gonof_common_member_appeal" => {
                    !only(&["status", "handler_uid", "resolution", "handled_at"])
                        || !condition.contains("status='pending'")
                }
                "gonof_common_data_request" => {
                    assigned.iter().any(|column| {
                        matches!(
                            column.as_str(),
                            "kind"
                                | "uid"
                                | "content_mode"
                                | "request_key"
                                | "request_hash"
                                | "dateline"
                                | "execute_after"
                        )
                    }) || !set.contains("version=version+1")
                        || (assigns("upper_pid") && !set.contains("upper_pid=greatest(upper_pid,"))
                }
                "gonof_common_outbox" => {
                    (assigns("available_at") && !set.contains("available_at=greatest(dateline,"))
                        || assigned.iter().any(|column| {
                            matches!(
                                column.as_str(),
                                "event_key"
                                    | "event_type"
                                    | "aggregate_type"
                                    | "aggregate_id"
                                    | "dateline"
                            )
                        })
                        || quoted_words(&set).any(|word| !OUTBOX_STATUSES.contains(&word))
                }
                "gonof_common_log"
                | "gonof_common_member_username_history"
                | "gonof_common_member_role_request"
                | "gonof_common_site_asset" => true,
                "gonof_common_settings" => assigns("skey"),
                _ => false,
            };
            if bad {
                found.push(format!(
                    "{file}:{line} UPDATE {table} SET {set} WHERE {condition}"
                ));
            }
        }
        for (line, table, assignments) in upsert_texts(&text) {
            let assigned = assigned_columns(&assignments);
            let only = |names: &[&str]| {
                assigned
                    .iter()
                    .all(|column| names.contains(&column.as_str()))
            };
            let assignments = squeeze(&assignments);
            let bad = match table.as_str() {
                "gonof_common_settings" => !only(&["svalue"]),
                "gonof_common_site_asset" => !only(&["aid", "version", "dateline"]),
                "gonof_common_member_username_history" => {
                    !only(&["expires_at"])
                        || !assignments.contains("expires_at=greatest(expires_at,")
                }
                "gonof_common_outbox" => {
                    (assigned.iter().any(|column| column == "available_at")
                        && !assignments.contains("available_at=greatest(dateline,"))
                        || quoted_words(&assignments).any(|word| !OUTBOX_STATUSES.contains(&word))
                }
                "gonof_common_member_token"
                | "gonof_common_member_api_key"
                | "gonof_common_invite"
                | "gonof_common_member"
                | "gonof_common_member_sanction"
                | "gonof_common_report"
                | "gonof_common_member_appeal"
                | "gonof_common_data_request"
                | "gonof_common_log"
                | "gonof_common_member_role_request" => !assigned.is_empty(),
                _ => false,
            };
            if bad {
                found.push(format!(
                    "{file}:{line} ON DUPLICATE KEY UPDATE {table} {assignments}"
                ));
            }
        }
    }
    assert!(
        found.is_empty(),
        "identity and governance tables are written only through identity/rules.rs and their own entry points: states only move forward, original content does not change, appeals, sanctions and reports are never deleted, and times are not earlier than issue: {found:?}"
    );
}

/// Private messages, follows, blocks, favorites, likes, requests, revisions and attachments, which have no triggers.
/// Values are checked at the write entry points (`messages::rules`, `media::check_new_upload` / `check_inspection`, the
/// request entry points in `identity::rules`, the parameter validation of each relation entry point); this pins "where
/// it may be written", "immutable" and "only grows":
/// - the three private message tables are written only in `messages.rs`, and message rows are never updated or
///   deleted; a conversation's last message changes only through the `last_message_id<?` conditional update; state
///   rows never change member or conversation, the read position and last time are only written with `GREATEST`, and
///   unread is only set to 0 or incremented;
/// - attachments are inserted only in `media.rs`, the two request tables only through `identity/rules.rs`, and
///   revisions only at the edit entry point, deleted only in account deletion erasure; follows, blocks, favorites,
///   likes, requests, revisions, attachment references and the attachment main table have no UPDATE; write statements
///   that build table names with `format!` are only allowed in the existing few places;
/// - attachment detail state and inspection results are only written with the literals in `media::LIFECYCLES` /
///   `SCAN_STATUSES`, the three time columns only with NULL or `GREATEST(dateline, …)`; ID, upload time, storage
///   location and configuration never change, the file name is changed only by account deletion erasure, and the
///   inspection result is written only by the statement that marks "passed inspection".
#[test]
fn messaging_social_and_attachment_rows_change_only_through_their_code() {
    const NO_UPDATE: &[&str] = &[
        "gonof_home_message",
        "gonof_forum_attachment",
        "gonof_forum_attachment_reference",
        "gonof_forum_post_reaction",
        "gonof_forum_post_request",
        "gonof_forum_post_revision",
        "gonof_home_favorite",
        "gonof_home_forum_follow",
        "gonof_home_interaction_request",
        "gonof_home_member_block",
        "gonof_home_thread_follow",
    ];
    const DYNAMIC: &[(&str, &[&str])] = &[
        ("\"UPDATE {", &["activities/worker.rs"]),
        (
            "\"INSERT INTO {",
            &[
                "interaction.rs",
                "interaction/social.rs",
                "activities/campaign.rs",
            ],
        ),
    ];
    let mut found = Vec::new();
    for (file, text) in production_sources() {
        let file = file.as_str();
        for (line, table, _) in inserts(&text) {
            let allowed: &[&str] = match table.as_str() {
                "gonof_home_message"
                | "gonof_home_message_member"
                | "gonof_home_message_thread" => &["messages.rs"],
                "gonof_forum_attachment" | "gonof_forum_attachment_0" => &["media.rs"],
                "gonof_forum_attachment_reference" => &["content/writes.rs", "content/edits.rs"],
                "gonof_forum_post_revision" => &["content/edits.rs"],
                "gonof_forum_post_request" | "gonof_home_interaction_request" => {
                    &["identity/rules.rs"]
                }
                _ => continue,
            };
            if !allowed.contains(&file) {
                found.push(format!("{file}:{line} INSERT {table}"));
            }
        }
        for (line, verb, table) in writes(&text) {
            let bad = match table.as_str() {
                "gonof_home_message" => verb != "insert",
                "gonof_home_message_thread"
                | "gonof_home_message_member"
                | "gonof_forum_attachment" => !matches!(verb, "insert" | "update"),
                "gonof_forum_post_revision" => {
                    !(verb == "insert" || (verb == "delete" && file == "privacy/worker.rs"))
                }
                _ => false,
            } || (verb == "update" && NO_UPDATE.contains(&table.as_str()))
                || (matches!(verb, "replace" | "truncate") && NO_UPDATE.contains(&table.as_str()));
            if bad {
                found.push(format!("{file}:{line} {verb} {table}"));
            }
        }
        for (marker, allowed) in DYNAMIC {
            if text.contains(marker) && !allowed.contains(&file) {
                found.push(format!(
                    "{file} builds a table name with format! for a write: {marker}"
                ));
            }
        }
        for (line, table, set, condition) in update_texts(&text) {
            let assigned = assigned_columns(&set);
            let only = |names: &[&str]| {
                assigned
                    .iter()
                    .all(|column| names.contains(&column.as_str()))
            };
            let assigns = |name: &str| assigned.iter().any(|column| column == name);
            let set = squeeze(&set);
            let condition = squeeze(&condition);
            let bad = match table.as_str() {
                "gonof_home_message_member" => {
                    !only(&["last_dateline", "unread", "last_read_id"])
                        || (assigns("last_dateline")
                            && !set.contains("last_dateline=greatest(last_dateline,"))
                        || (assigns("last_read_id")
                            && !set.contains("last_read_id=greatest(last_read_id,"))
                        || (assigns("unread")
                            && !(set.contains("unread=0") || set.contains("unread=unread+1")))
                }
                "gonof_home_message_thread" => {
                    !only(&["last_message_id"]) || !condition.contains("last_message_id<")
                }
                "gonof_forum_attachment_0" => {
                    ["updated_at", "checked_at", "purge_after"]
                        .iter()
                        .any(|column| {
                            assigns(column)
                                && !set.contains(&format!("{column}=null"))
                                && !set.contains(&format!("{column}=greatest(dateline,"))
                        })
                        || literal_assignments(&set, "lifecycle", assigns("lifecycle")).is_none_or(
                            |values| {
                                values
                                    .iter()
                                    .any(|v| !crate::media::LIFECYCLES.contains(&v.as_str()))
                            },
                        )
                        || literal_assignments(&set, "scan_status", assigns("scan_status"))
                            .is_none_or(|values| {
                                values
                                    .iter()
                                    .any(|v| !crate::media::SCAN_STATUSES.contains(&v.as_str()))
                            })
                        || ["aid", "dateline", "attachment", "storage_profile_id"]
                            .iter()
                            .any(|column| assigns(column))
                        || (assigns("filename") && file != "privacy/worker.rs")
                        || (["mime_type", "content_sha256", "filesize", "width", "height"]
                            .iter()
                            .any(|column| assigns(column))
                            && file != "media/worker.rs")
                }
                _ => false,
            };
            if bad {
                found.push(format!(
                    "{file}:{line} UPDATE {table} SET {set} WHERE {condition}"
                ));
            }
        }
        for (line, table, assignments) in upsert_texts(&text) {
            let assigned = assigned_columns(&assignments);
            let bad = match table.as_str() {
                "gonof_home_message_thread" => assigned != ["id"],
                "gonof_home_message_member" => assigned != ["thread_id"],
                "gonof_home_message" | "gonof_forum_attachment" | "gonof_forum_attachment_0" => {
                    true
                }
                _ => false,
            };
            if bad {
                found.push(format!(
                    "{file}:{line} ON DUPLICATE KEY UPDATE {table} {assigned:?}"
                ));
            }
        }
        let lower = text.to_ascii_lowercase();
        let mut from = 0;
        while let Some(offset) = lower[from..].find("insert into gonof_forum_attachment_0") {
            let start = from + offset;
            from = start + 10;
            let statement = statement_at(&text, start);
            if quoted_words(&statement).any(|word| {
                !crate::media::LIFECYCLES.contains(&word)
                    && !crate::media::SCAN_STATUSES.contains(&word)
            }) {
                found.push(format!(
                    "{file} writes an unregistered state into a new attachment: {statement}"
                ));
            }
        }
    }
    assert!(
        found.is_empty(),
        "message, attachment, request, revision and relation tables are written only through their own entry points: messages are never changed or deleted, grow-only columns are written only with GREATEST or a conditional update, attachment states only take registered values, and times are not earlier than upload: {found:?}"
    );
}

#[test]
fn scanner_reads_column_lists_and_assignments() {
    let text = "let a = \"INSERT INTO gonof_common_member (uid, username) VALUES (?, ?)\";\n\
        let b = \"insert ignore into `gonof_forum_thread`(fid,subject) VALUES(?,?)\";\n\
        let c = \"UPDATE gonof_forum_thread t JOIN gonof_forum_post p ON p.pid=t.last_reply_pid SET t.tid=?, last_reply_author=? WHERE p.authorid=?\";\n\
        let d = \"UPDATE gonof_common_member SET username=? WHERE uid=?\";\n\
        let e = \"DELETE FROM gonof_home_notification WHERE uid=?\";";
    assert_eq!(
        deletes(text),
        vec![(5, "gonof_home_notification".to_owned())]
    );
    assert_eq!(
        writes(
            "REPLACE INTO gonof_common_credit_ledger(id) VALUES(1); TRUNCATE TABLE gonof_common_growth_ledger; SELECT 1 FOR UPDATE"
        ),
        vec![
            (1, "replace", "gonof_common_credit_ledger".to_owned()),
            (1, "truncate", "gonof_common_growth_ledger".to_owned()),
        ]
    );
    assert_eq!(
        inserts(text),
        vec![
            (
                1,
                "gonof_common_member".to_owned(),
                vec!["uid".to_owned(), "username".to_owned()]
            ),
            (
                2,
                "gonof_forum_thread".to_owned(),
                vec!["fid".to_owned(), "subject".to_owned()]
            ),
        ]
    );
    assert_eq!(
        updates(text),
        vec![
            (
                3,
                "gonof_forum_thread".to_owned(),
                vec!["tid".to_owned(), "last_reply_author".to_owned()]
            ),
            (
                4,
                "gonof_common_member".to_owned(),
                vec!["username".to_owned()]
            ),
        ]
    );
}

pub(crate) fn production_sources() -> Vec<(String, String)> {
    let root = crate::project_root().join("apps/web/src");
    let mut files = Vec::new();
    collect(&root, &root, &mut files);
    files.sort();
    assert!(
        files.len() > 50,
        "no source files were read: {}",
        root.display()
    );
    files
}

fn collect(root: &Path, dir: &Path, files: &mut Vec<(String, String)>) {
    for entry in std::fs::read_dir(dir).unwrap() {
        let path = entry.unwrap().path();
        if path.is_dir() {
            collect(root, &path, files);
            continue;
        }
        let name = path.file_name().unwrap().to_string_lossy().into_owned();
        if !name.ends_with(".rs")
            || name == "tests.rs"
            || name.ends_with("_tests.rs")
            || name == "test_support.rs"
        {
            continue;
        }
        let mut text = std::fs::read_to_string(&path).unwrap();
        // Only test modules written inline in the file (`mod tests {`) are cut off. `#[cfg(test)] mod tests;` is just a
        // declaration and production code follows it (media.rs is like that; cutting there would skip every write
        // statement after it).
        if let Some(cut) = text.find("#[cfg(test)]\nmod tests {") {
            text.truncate(cut);
        }
        let relative = path
            .strip_prefix(root)
            .unwrap()
            .to_string_lossy()
            .replace('\\', "/");
        // The sample SQL in this file is for the scanner's self-tests, not a write path.
        if relative != "db/source_guards.rs" {
            files.push((relative, text));
        }
    }
}

#[derive(Debug, PartialEq)]
enum Token {
    Word(String),
    Mark(char),
}

/// Rough tokenizer: an identifier (digits and underscores included) is one word, each of `( ) , = . "` is one symbol,
/// and everything else (whitespace, backticks) is skipped. Returns (line number, word). Only meant to recognize the
/// skeleton of SQL in source, not a full parse.
fn tokens(text: &str) -> Vec<(usize, Token)> {
    let mut out = Vec::new();
    let mut line = 1;
    let mut chars = text.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\n' {
            line += 1;
        } else if c.is_ascii_alphanumeric() || c == '_' {
            let mut word = String::from(c.to_ascii_lowercase());
            while let Some(&next) = chars.peek() {
                if !(next.is_ascii_alphanumeric() || next == '_') {
                    break;
                }
                word.push(next.to_ascii_lowercase());
                chars.next();
            }
            out.push((line, Token::Word(word)));
        } else if matches!(c, '(' | ')' | ',' | '=' | '.' | '"') {
            out.push((line, Token::Mark(c)));
        }
    }
    out
}

fn word(token: Option<&(usize, Token)>) -> Option<&str> {
    match token {
        Some((_, Token::Word(word))) => Some(word),
        _ => None,
    }
}

/// `INSERT|REPLACE [IGNORE] INTO table (columns, …)`: returns (line number, table, columns).
fn inserts(text: &str) -> Vec<(usize, String, Vec<String>)> {
    let tokens = tokens(text);
    let mut found = Vec::new();
    for (index, (line, token)) in tokens.iter().enumerate() {
        if !matches!(token, Token::Word(w) if w == "insert" || w == "replace") {
            continue;
        }
        let mut at = index + 1;
        if word(tokens.get(at)) == Some("ignore") {
            at += 1;
        }
        if word(tokens.get(at)) != Some("into") {
            continue;
        }
        let Some(table) = word(tokens.get(at + 1)) else {
            continue;
        };
        if tokens.get(at + 2).map(|(_, token)| token) != Some(&Token::Mark('(')) {
            continue;
        }
        let mut columns = Vec::new();
        let mut expect_column = true;
        for (_, token) in &tokens[at + 3..] {
            match token {
                Token::Mark(')') => break,
                Token::Mark(',') => expect_column = true,
                Token::Word(column) if expect_column => {
                    columns.push(column.clone());
                    expect_column = false;
                }
                _ => {}
            }
        }
        found.push((*line, table.to_owned(), columns));
    }
    found
}

/// Skeleton of write statements: the `gonof_` table following `INSERT [IGNORE] INTO`, `REPLACE INTO`, `UPDATE`,
/// `DELETE FROM` or `TRUNCATE [TABLE]`; returns (line number, verb, table).
fn writes(text: &str) -> Vec<(usize, &'static str, String)> {
    let tokens = tokens(text);
    let mut found = Vec::new();
    for (index, (line, token)) in tokens.iter().enumerate() {
        let Token::Word(verb) = token else {
            continue;
        };
        let (verb, skip): (&'static str, &[&str]) = match verb.as_str() {
            "insert" => ("insert", &["ignore", "into"]),
            "replace" => ("replace", &["into"]),
            "update" => ("update", &[]),
            "delete" => ("delete", &["from"]),
            "truncate" => ("truncate", &["table"]),
            _ => continue,
        };
        let mut at = index + 1;
        while word(tokens.get(at)).is_some_and(|word| skip.contains(&word)) {
            at += 1;
        }
        if let Some(table) = word(tokens.get(at))
            && table.starts_with("gonof_")
        {
            found.push((*line, verb, table.to_owned()));
        }
    }
    found
}

/// `DELETE FROM table`: returns (line number, table).
fn deletes(text: &str) -> Vec<(usize, String)> {
    let tokens = tokens(text);
    let mut found = Vec::new();
    for (index, (line, token)) in tokens.iter().enumerate() {
        if matches!(token, Token::Word(w) if w == "delete")
            && word(tokens.get(index + 1)) == Some("from")
            && let Some(table) = word(tokens.get(index + 2))
        {
            found.push((*line, table.to_owned()));
        }
    }
    found
}

/// `UPDATE table … SET a=…, b=… WHERE`: returns (line number, table, assigned columns). The assignment section runs
/// until `WHERE` or the end of the string.
fn updates(text: &str) -> Vec<(usize, String, Vec<String>)> {
    let tokens = tokens(text);
    let mut found = Vec::new();
    for (index, (line, token)) in tokens.iter().enumerate() {
        if !matches!(token, Token::Word(w) if w == "update") {
            continue;
        }
        let Some(table) = word(tokens.get(index + 1)) else {
            continue;
        };
        let Some(set) = tokens[index + 2..]
            .iter()
            .take_while(|(_, token)| *token != Token::Mark('"'))
            .position(|(_, token)| matches!(token, Token::Word(w) if w == "set"))
            .map(|offset| index + 2 + offset)
        else {
            continue;
        };
        let mut assigned = Vec::new();
        let region: Vec<&Token> = tokens[set..]
            .iter()
            .map(|(_, token)| token)
            .take_while(|token| {
                !matches!(token, Token::Word(w) if w == "where") && **token != Token::Mark('"')
            })
            .collect();
        for triple in region.windows(3) {
            let starts_assignment = matches!(triple[0], Token::Word(w) if w == "set")
                || matches!(triple[0], Token::Mark(',' | '.'));
            if let Token::Word(column) = triple[1]
                && starts_assignment
                && *triple[2] == Token::Mark('=')
            {
                assigned.push(column.clone());
            }
        }
        found.push((*line, table.to_owned(), assigned));
    }
    found
}

/// Removes all whitespace so SQL can be compared by fragment (`a = GREATEST(dateline, ?)` → `a=greatest(dateline,?)`).
/// Callers already pass lowercase.
fn squeeze(text: &str) -> String {
    text.chars().filter(|c| !c.is_whitespace()).collect()
}

/// The assigned columns in an assignment section: `a=…, t.b=…` → `[a, b]`. Commas may appear in function arguments, so
/// only "a word directly followed by `=` and preceded by the section start, a comma or a dot" counts, as in
/// [`updates`].
fn assigned_columns(assignments: &str) -> Vec<String> {
    let text = format!("set {assignments}");
    let tokens: Vec<Token> = tokens(&text).into_iter().map(|(_, token)| token).collect();
    let mut columns = Vec::new();
    for triple in tokens.windows(3) {
        let starts = matches!(&triple[0], Token::Word(w) if w == "set")
            || matches!(triple[0], Token::Mark(',' | '.'));
        if let Token::Word(column) = &triple[1]
            && starts
            && triple[2] == Token::Mark('=')
        {
            columns.push(column.clone());
        }
    }
    columns
}

/// Pure identifier literals in single quotes (`'pending'`, `'sent'`), used to check literals written into state
/// columns; text with spaces, symbols or Chinese (error messages, JSON) does not count.
fn quoted_words(text: &str) -> impl Iterator<Item = &str> {
    text.split('\'').skip(1).step_by(2).filter(|word| {
        !word.is_empty() && word.bytes().all(|b| b.is_ascii_lowercase() || b == b'_')
    })
}

/// The span from `start` to the end of the enclosing Rust string literal (the next unescaped `"`), lowercased.
fn statement_at(text: &str, start: usize) -> String {
    let bytes = text.as_bytes();
    let mut end = start;
    while end < bytes.len() && !(bytes[end] == b'"' && bytes[end - 1] != b'\\') {
        end += 1;
    }
    text[start..end].to_ascii_lowercase()
}

/// The text of `UPDATE table … SET … [WHERE …]`: returns (line number, table, SET section, WHERE section), lowercased.
/// A statement runs until the end of its string literal; `ON DUPLICATE KEY UPDATE` is not followed by a `gonof_` table
/// and is not handled here (see [`upsert_texts`]).
fn update_texts(text: &str) -> Vec<(usize, String, String, String)> {
    let lower = text.to_ascii_lowercase();
    let mut found = Vec::new();
    let mut from = 0;
    while let Some(offset) = lower[from..].find("update") {
        let start = from + offset;
        from = start + 6;
        let before = lower[..start].bytes().next_back();
        if before.is_some_and(|b| b.is_ascii_alphanumeric() || b == b'_') {
            continue;
        }
        let rest = lower[start + 6..].trim_start_matches(|c: char| c.is_whitespace() || c == '`');
        let table: String = rest
            .chars()
            .take_while(|c| c.is_ascii_alphanumeric() || *c == '_')
            .collect();
        if !table.starts_with("gonof_") {
            continue;
        }
        let statement = statement_at(text, start);
        let Some(set) = word_at(&statement, "set") else {
            continue;
        };
        let body = &statement[set + 3..];
        let (assignments, condition) = match word_at(body, "where") {
            Some(at) => (&body[..at], &body[at + 5..]),
            None => (body, ""),
        };
        let line = text[..start].matches('\n').count() + 1;
        found.push((line, table, assignments.to_owned(), condition.to_owned()));
    }
    found
}

/// `INSERT … INTO table … ON DUPLICATE KEY UPDATE …`: returns (line number, table, assignment section on duplicate),
/// lowercased.
fn upsert_texts(text: &str) -> Vec<(usize, String, String)> {
    let lower = text.to_ascii_lowercase();
    let mut found = Vec::new();
    let mut from = 0;
    while let Some(offset) = lower[from..].find("insert") {
        let start = from + offset;
        from = start + 6;
        let statement = statement_at(text, start);
        let Some(into) = word_at(&statement, "into") else {
            continue;
        };
        let table: String = statement[into + 4..]
            .trim_start_matches(|c: char| c.is_whitespace() || c == '`')
            .chars()
            .take_while(|c| c.is_ascii_alphanumeric() || *c == '_')
            .collect();
        let Some(update) = statement.find("on duplicate key update") else {
            continue;
        };
        if !table.starts_with("gonof_") {
            continue;
        }
        let line = text[..start].matches('\n').count() + 1;
        found.push((line, table, statement[update + 23..].to_owned()));
    }
    found
}

/// Positions of whole-word occurrences (not preceded or followed by a letter, digit or underscore).
fn word_at(text: &str, word: &str) -> Option<usize> {
    let bytes = text.as_bytes();
    let boundary = |b: Option<&u8>| !b.is_some_and(|b| b.is_ascii_alphanumeric() || *b == b'_');
    let mut from = 0;
    while let Some(offset) = text[from..].find(word) {
        let at = from + offset;
        if boundary(at.checked_sub(1).and_then(|i| bytes.get(i)))
            && boundary(bytes.get(at + word.len()))
        {
            return Some(at);
        }
        from = at + word.len();
    }
    None
}

/// The literals assigned to `column` in an assignment section (`lifecycle='ready'` → `["ready"]`). Returns `None` when
/// the column is assigned something that is not a literal (a bound parameter, an expression), and an empty list when
/// it is not assigned. `set` already has whitespace removed.
fn literal_assignments(set: &str, column: &str, assigned: bool) -> Option<Vec<String>> {
    let mut values = Vec::new();
    let pattern = format!("{column}='");
    let mut from = 0;
    while let Some(offset) = set[from..].find(&pattern) {
        let at = from + offset;
        let before = set[..at].bytes().next_back();
        let start = at + pattern.len();
        from = start;
        if before.is_some_and(|b| b.is_ascii_alphanumeric() || b == b'_') {
            continue;
        }
        let end = set[start..].find('\'')? + start;
        values.push(set[start..end].to_owned());
    }
    (!assigned || !values.is_empty()).then_some(values)
}
